// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Img, spring, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type SpotifyPlayerProps = Record<string, any>;

const SpotifyPlayer: React.FC<SpotifyPlayerProps> = ({
  backgroundColor = "#09090b",
  transparentBackground = false,
  durationInSeconds = 20,
  trackTitle = "Midnight City",
  artistName = "M83",
  albumArtUrl = "https://images.unsplash.com/photo-1614613535308-eb5fbd3d2c17?q=80&w=600&auto=format&fit=crop",
  totalDurationText = "3:45",
  glowIntensity = 0.55,
  accentColor = "#1DB954",
  lyricsList = [
    "Waiting in a car",
    "Waiting for a start in the dark",
    "The city is my church",
    "It wraps me in its neon arms",
    "Suddenly, the sky is filled with light",
    "We own the night",
    "We own the night",
    "Walking on the edge of a dream",
    "Midnight city glows",
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Music active/play transition settings (tap to play at frame 15)
  const playTapFrame = 15;
  const isPlaying = frame >= playTapFrame;
  const activeFrame = isPlaying ? frame - playTapFrame : 0;
  const activeDuration = Math.max(1, durationInFrames - playTapFrame);

  // Background and Ambient Lighting Animations
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const ambientPulse = Math.sin(frame * 0.03) * 0.1 + 0.9;

  // Background blobs movement (strictly increasing ranges)
  const blob1X = interpolate(Math.sin(frame * 0.012), [-1, 1], [15, 35]);
  const blob1Y = interpolate(Math.cos(frame * 0.015), [-1, 1], [20, 40]);
  const blob2X = interpolate(Math.cos(frame * 0.010), [-1, 1], [65, 85]);
  const blob2Y = interpolate(Math.sin(frame * 0.013), [-1, 1], [50, 70]);

  // Entrance spring animations
  const cardEntrance = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 70 },
  });
  const cardScale = interpolate(cardEntrance, [0, 1], [0.92, 1]);
  const cardOpacity = interpolate(cardEntrance, [0, 1], [0, 1]);

  const albumSpring = spring({
    frame,
    fps,
    config: { damping: 15 },
  });
  const albumScale = interpolate(albumSpring, [0, 1], [0.85, 1]);

  // Progress Bar Filling (0% to 100%)
  const progressPercent = isPlaying
    ? interpolate(activeFrame, [0, activeDuration], [0, 100], {
        extrapolateRight: "clamp",
      })
    : 0;

  // Timing formatting
  const elapsedSecondsTotal = isPlaying ? Math.floor(activeFrame / fps) : 0;
  const elapsedMin = Math.floor(elapsedSecondsTotal / 60);
  const elapsedSec = elapsedSecondsTotal % 60;
  const elapsedStr = `${elapsedMin}:${elapsedSec < 10 ? "0" : ""}${elapsedSec}`;

  // Interactive Play Button Tap animation
  const tapSpring = spring({
    frame: frame - playTapFrame,
    fps,
    config: { damping: 10, mass: 0.5 },
  });
  const playButtonScale = isPlaying
    ? interpolate(tapSpring, [0, 0.2, 1], [1, 0.82, 1])
    : 1;

  // Interactive Ripple Ripple effect around play button
  const rippleSpring = spring({
    frame: frame - playTapFrame,
    fps,
    config: { damping: 15, stiffness: 60 },
  });
  const rippleSize = interpolate(rippleSpring, [0, 1], [64, 160]);
  const rippleOpacity = isPlaying
    ? interpolate(rippleSpring, [0, 1], [0.8, 0], { extrapolateRight: "clamp" })
    : 0;

  // Lyrics Sync calculation
  const lyricProgress = isPlaying ? activeFrame / activeDuration : 0;
  const activeLyricIndex = Math.min(
    lyricsList.length - 1,
    Math.floor(lyricProgress * lyricsList.length)
  );
  
  // Clean scroll interpolation of lyrics viewport
  const LYRIC_ROW_HEIGHT = 78;
  const lyricsTranslateY = -activeLyricIndex * LYRIC_ROW_HEIGHT;

  // Realistic deterministic spectrum analyzer (Audio visualizer)
  const VISUALIZER_BARS_COUNT = 24;
  const bars = Array.from({ length: VISUALIZER_BARS_COUNT }).map((_, index) => {
    const seed = `spectrum-bar-${index}`;
    const speedFactor = 0.16 + random(seed + "-speed") * 0.12;
    const phase = random(seed + "-phase") * Math.PI * 2;
    const rawValue = Math.sin(frame * speedFactor + phase);
    const amplitude = (rawValue + 1) / 2;
    
    // Scale visualization based on play status
    const multiplier = isPlaying
      ? interpolate(activeFrame, [0, 15], [0, 1], { extrapolateRight: "clamp" })
      : 0;
    return 10 + amplitude * 80 * multiplier;
  });

  // Safe Responsive sizing constants
  const cardWidth = Math.min(width * 0.28, 480);
  const cardHeight = Math.min(height * 0.82, 880);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        overflow: "hidden",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        color: "#ffffff",
      }}
    >
      {/* Background Animated Gradient Blobs */}
      {!transparentBackground && (
        <>
          <div
            style={{
              position: "absolute",
              width: 600,
              height: 600,
              borderRadius: "50%",
              background: `radial-gradient(circle, ${accentColor}33 0%, transparent 70%)`,
              left: `${blob1X}%`,
              top: `${blob1Y}%`,
              filter: "blur(80px)",
              transform: `scale(${ambientPulse})`,
              pointerEvents: "none",
              transition: "none",
            }}
          />
          <div
            style={{
              position: "absolute",
              width: 700,
              height: 700,
              borderRadius: "50%",
              background: "radial-gradient(circle, #7c3aed22 0%, transparent 70%)",
              left: `${blob2X}%`,
              top: `${blob2Y}%`,
              filter: "blur(90px)",
              transform: `scale(${2.1 - ambientPulse})`,
              pointerEvents: "none",
              transition: "none",
            }}
          />
        </>
      )}

      {/* Main Content Layout Container */}
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          justifyContent: "center",
          alignItems: "center",
          width: "100%",
          height: "100%",
          padding: `0 ${width * 0.05}px`,
          boxSizing: "border-box",
          gap: 60,
          zIndex: 10,
          transition: "none",
        }}
      >
        {/* Left Column: Spotify Mobile Player Frame */}
        <div
          style={{
            width: cardWidth,
            height: cardHeight,
            backgroundColor: "rgba(18, 18, 18, 0.72)",
            borderRadius: 36,
            border: "1px solid rgba(255, 255, 255, 0.08)",
            boxShadow: "0 30px 70px rgba(0, 0, 0, 0.8)",
            padding: "28px 24px",
            boxSizing: "border-box",
            display: "flex",
            flexDirection: "column",
            justifyContent: "space-between",
            position: "relative",
            overflow: "hidden",
            backdropFilter: "blur(24px)",
            opacity: cardOpacity,
            transform: `scale(${cardScale})`,
            transition: "none",
          }}
        >
          {/* Header */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              color: "rgba(255, 255, 255, 0.5)",
              fontSize: 10,
              fontWeight: 700,
              letterSpacing: 1.5,
              textTransform: "uppercase",
              transition: "none",
            }}
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M6 9l6 6 6-6" />
            </svg>
            <span>PLAYING FROM PLAYLIST</span>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <circle cx="12" cy="12" r="1" />
              <circle cx="12" cy="5" r="1" />
              <circle cx="12" cy="19" r="1" />
            </svg>
          </div>

          {/* Large Rounded Album Art */}
          <div
            style={{
              position: "relative",
              width: "100%",
              aspectRatio: "1/1",
              borderRadius: 20,
              overflow: "visible",
              margin: "12px 0",
              transition: "none",
            }}
          >
            {/* Soft Shadow / Backing Glow */}
            <div
              style={{
                position: "absolute",
                top: "6%",
                left: "6%",
                width: "88%",
                height: "88%",
                backgroundImage: `url(${albumArtUrl})`,
                backgroundSize: "cover",
                backgroundPosition: "center",
                filter: "blur(24px)",
                opacity: glowIntensity * (isPlaying ? 1.05 : 0.8),
                zIndex: 0,
                borderRadius: 20,
                transform: `scale(${albumScale * (1 + Math.sin(frame * 0.04) * 0.02)})`,
                transition: "none",
              }}
            />
            {/* Foreground Album Image */}
            <Img
              src={albumArtUrl}
              style={{
                position: "relative",
                width: "100%",
                height: "100%",
                borderRadius: 20,
                objectFit: "cover",
                zIndex: 1,
                boxShadow: "0 12px 35px rgba(0, 0, 0, 0.5)",
                transform: `scale(${albumScale})`,
                transition: "none",
              }}
            />
          </div>

          {/* Metadata Section */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              margin: "6px 0",
              transition: "none",
            }}
          >
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                flex: 1,
                paddingRight: 10,
                overflow: "hidden",
                transition: "none",
              }}
            >
              <h2
                style={{
                  color: "#ffffff",
                  fontSize: 22,
                  fontWeight: 800,
                  margin: 0,
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  letterSpacing: -0.5,
                  transition: "none",
                }}
              >
                {trackTitle}
              </h2>
              <p
                style={{
                  color: "rgba(255, 255, 255, 0.55)",
                  fontSize: 14,
                  fontWeight: 500,
                  margin: "4px 0 0 0",
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  transition: "none",
                }}
              >
                {artistName}
              </p>
            </div>
            {/* Heart Active State */}
            <svg
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill={accentColor}
              stroke={accentColor}
              strokeWidth="1"
              style={{ cursor: "pointer", filter: `drop-shadow(0 0 8px ${accentColor}40)`, transition: "none" }}
            >
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </div>

          {/* Progress Bar Container */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              width: "100%",
              margin: "12px 0 6px 0",
              transition: "none",
            }}
          >
            {/* Track Line */}
            <div
              style={{
                width: "100%",
                height: 4,
                backgroundColor: "rgba(255, 255, 255, 0.16)",
                borderRadius: 2,
                position: "relative",
                cursor: "pointer",
                transition: "none",
              }}
            >
              {/* Green Progress */}
              <div
                style={{
                  width: `${progressPercent}%`,
                  height: "100%",
                  backgroundColor: accentColor,
                  borderRadius: 2,
                  position: "absolute",
                  left: 0,
                  top: 0,
                  boxShadow: `0 0 10px ${accentColor}80`,
                  transition: "none",
                }}
              />
              {/* Progress Pin */}
              <div
                style={{
                  width: 12,
                  height: 12,
                  backgroundColor: "#ffffff",
                  borderRadius: "50%",
                  position: "absolute",
                  left: `calc(${progressPercent}% - 6px)`,
                  top: -4,
                  boxShadow: "0 2px 6px rgba(0,0,0,0.6)",
                  transition: "none",
                }}
              />
            </div>

            {/* Timestamps */}
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                marginTop: 8,
                fontSize: 11,
                fontWeight: 600,
                color: "rgba(255, 255, 255, 0.5)",
                letterSpacing: 0.2,
                transition: "none",
              }}
            >
              <span>{elapsedStr}</span>
              <span>{totalDurationText}</span>
            </div>
          </div>

          {/* Spotify Media Control Layout */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              width: "100%",
              margin: "4px 0",
              transition: "none",
            }}
          >
            {/* Shuffle Toggle */}
            <div
              style={{
                color: accentColor,
                position: "relative",
                cursor: "pointer",
                transition: "none",
              }}
            >
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2">
                <path d="M16 3h5v5" />
                <path d="M4 20L21 3" />
                <path d="M21 16v5h-5" />
                <path d="M15 15l6 6" />
                <path d="M4 4l5 5" />
              </svg>
              {/* Active Dot */}
              <div
                style={{
                  width: 4,
                  height: 4,
                  borderRadius: "50%",
                  backgroundColor: accentColor,
                  position: "absolute",
                  bottom: -8,
                  left: "50%",
                  transform: "translateX(-50%)",
                  boxShadow: `0 0 6px ${accentColor}`,
                  transition: "none",
                }}
              />
            </div>

            {/* Skip Previous */}
            <div style={{ color: "#ffffff", cursor: "pointer", transition: "none" }}>
              <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor">
                <path d="M6 19h2V5H6v14zm3.5-7L18 5v14l-8.5-7z" />
              </svg>
            </div>

            {/* Central Play/Pause Button */}
            <div style={{ position: "relative", transition: "none" }}>
              {/* Expand ripple when active */}
              {isPlaying && (
                <div
                  style={{
                    position: "absolute",
                    top: "50%",
                    left: "50%",
                    transform: "translate(-50%, -50%)",
                    width: rippleSize,
                    height: rippleSize,
                    borderRadius: "50%",
                    border: "2px solid rgba(255, 255, 255, 0.4)",
                    opacity: rippleOpacity,
                    pointerEvents: "none",
                    transition: "none",
                  }}
                />
              )}
              <div
                style={{
                  width: 64,
                  height: 64,
                  borderRadius: "50%",
                  backgroundColor: "#ffffff",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  color: "#000000",
                  boxShadow: "0 6px 20px rgba(255, 255, 255, 0.2)",
                  cursor: "pointer",
                  transform: `scale(${playButtonScale})`,
                  transition: "none",
                }}
              >
                <svg width="28" height="28" viewBox="0 0 24 24" fill="currentColor">
                  {isPlaying ? (
                    <path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z" />
                  ) : (
                    <path d="M8 5v14l11-7z" />
                  )}
                </svg>
              </div>
            </div>

            {/* Skip Next */}
            <div style={{ color: "#ffffff", cursor: "pointer", transition: "none" }}>
              <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor">
                <path d="M6 5v14l8.5-7L6 5zm9 14h2V5h-2v14z" />
              </svg>
            </div>

            {/* Repeat Toggle */}
            <div
              style={{
                color: accentColor,
                position: "relative",
                cursor: "pointer",
                transition: "none",
              }}
            >
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2">
                <path d="M17 1l4 4-4 4" />
                <path d="M3 11V9a4 4 0 0 1 4-4h14" />
                <path d="M7 23l-4-4 4-4" />
                <path d="M21 13v2a4 4 0 0 1-4 4H3" />
              </svg>
              {/* Active Dot */}
              <div
                style={{
                  width: 4,
                  height: 4,
                  borderRadius: "50%",
                  backgroundColor: accentColor,
                  position: "absolute",
                  bottom: -8,
                  left: "50%",
                  transform: "translateX(-50%)",
                  boxShadow: `0 0 6px ${accentColor}`,
                  transition: "none",
                }}
              />
            </div>
          </div>
        </div>

        {/* Right Column: Lyrics Sync Panel */}
        <div
          style={{
            flex: 1,
            maxWidth: 620,
            height: cardHeight,
            display: "flex",
            flexDirection: "column",
            justifyContent: "space-between",
            position: "relative",
            padding: "20px 0",
            boxSizing: "border-box",
            overflow: "hidden",
            transition: "none",
          }}
        >
          {/* Header Badge */}
          <div
            style={{
              fontSize: 12,
              fontWeight: 800,
              color: accentColor,
              letterSpacing: 3,
              textTransform: "uppercase",
              transition: "none",
              display: "flex",
              alignItems: "center",
              gap: 8,
            }}
          >
            <span
              style={{
                width: 6,
                height: 6,
                borderRadius: "50%",
                backgroundColor: isPlaying ? accentColor : "rgba(255,255,255,0.3)",
                display: "inline-block",
                boxShadow: isPlaying ? `0 0 10px ${accentColor}` : "none",
              }}
            />
            Lyrics Syncing
          </div>

          {/* Lyric Scroller Container */}
          <div
            style={{
              position: "relative",
              width: "100%",
              height: "75%",
              overflow: "hidden",
              transition: "none",
              margin: "24px 0",
            }}
          >
            {/* Top and Bottom Fades */}
            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                height: 70,
                background: "linear-gradient(to bottom, #09090b, transparent)",
                zIndex: 2,
                pointerEvents: "none",
                transition: "none",
              }}
            />
            <div
              style={{
                position: "absolute",
                bottom: 0,
                left: 0,
                right: 0,
                height: 70,
                background: "linear-gradient(to top, #09090b, transparent)",
                zIndex: 2,
                pointerEvents: "none",
                transition: "none",
              }}
            />

            {/* Lyrics Scroll Wheel */}
            <div
              style={{
                transform: `translateY(${lyricsTranslateY}px)`,
                transition: "none",
                display: "flex",
                flexDirection: "column",
                gap: 32,
                paddingTop: "140px", // Baseline offset to align index 0 in vertical center
              }}
            >
              {lyricsList.map((lyric, index) => {
                const isActive = index === activeLyricIndex;
                const distance = Math.abs(index - activeLyricIndex);
                
                // Fine-tune scale and transparency logic per frame
                const opacity = isActive
                  ? 1
                  : interpolate(distance, [0, 1, 2.5], [1, 0.42, 0.12], {
                      extrapolateRight: "clamp",
                    });
                const scale = isActive ? 1.04 : 0.95;
                const textGlow = isActive
                  ? `0 0 25px rgba(255, 255, 255, 0.15)`
                  : "none";

                return (
                  <div
                    key={index}
                    style={{
                      color: isActive ? "#ffffff" : "rgba(255, 255, 255, 0.8)",
                      fontSize: isActive ? 34 : 26,
                      fontWeight: isActive ? 800 : 600,
                      opacity,
                      transform: `scale(${scale})`,
                      transformOrigin: "left center",
                      transition: "none",
                      lineHeight: 1.35,
                      textShadow: textGlow,
                      maxWidth: "95%",
                      letterSpacing: -0.6,
                    }}
                  >
                    {lyric}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Spectrum Analyzer Waves */}
          <div
            style={{
              display: "flex",
              alignItems: "flex-end",
              gap: 5,
              height: 55,
              width: "100%",
              transition: "none",
            }}
          >
            {bars.map((barHeight, index) => (
              <div
                key={index}
                style={{
                  flex: 1,
                  height: `${barHeight}%`,
                  backgroundColor: accentColor,
                  borderRadius: 3,
                  opacity: interpolate(barHeight, [10, 90], [0.35, 1]),
                  boxShadow: `0 0 12px ${accentColor}33`,
                  transition: "none",
                }}
              />
            ))}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SpotifyPlayer;